fn main() {
    let x: u8 = 255;
    let y = x + 1;
    println!("{y}");
}

fn main() {
    let x: i32 = 300;
    let y = x as u8;
    println!("{y}");
}

fn main() {
    let x = 0.1 + 0.2;
    println!("{}", x == 0.3);
}

fn main() {
    let a = [1, 2, 3];
    let x = a[5];
    println!("{x}");
}

fn main() {
    let a = [1, 2, 3];
    let i = get_index();
    println!("{}", a[i]);
}

fn get_index() -> usize {
    5
}

fn main() {
    let x: i32 = -1;
    let y = x as u32;
    println!("{y}");
}

fn log_event(msg: &str) -> () {
    println!("{msg}");
}

fn main() {
    let result = log_event("started");
    println!("{result:?}");
}

fn main() {
    let result: Result<u8, _> = "300".parse();
    println!("{result:?}");
}
